import { useState, useRef } from 'react';

export function useCalendarGridInteraction({ courts = [], openingHour = 7, closingHour = 21, onSelectionComplete }) {
    const [isDragging, setIsDragging] = useState(false);
    const [selectionStart, setSelectionStart] = useState(null); // { courtId, timeInMinutes }
    const [selectionEnd, setSelectionEnd] = useState(null);     // { courtId, timeInMinutes }
    // Helper: converting time to grid index or vice-versa could go here
    // For now, we store raw data: Court ID and Minutes from midnight.

    const handleMouseDown = (courtId, timeInMinutes) => {
        setIsDragging(true);
        setSelectionStart({ courtId, timeInMinutes });
        setSelectionEnd({ courtId, timeInMinutes });
    };

    const handleMouseEnter = (courtId, timeInMinutes) => {
        if (!isDragging) return;
        setSelectionEnd({ courtId, timeInMinutes });
    };

    const handleMouseUp = () => {
        if (!isDragging) return;
        setIsDragging(false);

        // Normalize selection
        if (selectionStart && selectionEnd) {
            // Calculate start/end times
            const startTime = Math.min(selectionStart.timeInMinutes, selectionEnd.timeInMinutes);
            // For end time, since we select "blocks", if I drag from 9:00 to 10:00, the end is actually 11:00 (end of 10:00 block)?
            // Let's assume the selection target is the "Slot Start Time".
            // So if I drag to 10:30 slot, I want to include that slot.
            // Assuming 30-min slots.
            // If start=9:00, end=9:00 -> Duration 30 mins (ends 9:30).
            const rawEndTime = Math.max(selectionStart.timeInMinutes, selectionEnd.timeInMinutes);
            const endTime = rawEndTime + 30; // +30 mins to cover the selected slot

            // Calculate court range
            // Map court IDs to indices to find range
            const startCourtIndex = courts.findIndex(c => String(c.id) === String(selectionStart.courtId));
            const endCourtIndex = courts.findIndex(c => String(c.id) === String(selectionEnd.courtId));

            const minIndex = Math.min(startCourtIndex, endCourtIndex);
            const maxIndex = Math.max(startCourtIndex, endCourtIndex);

            const selectedCourts = courts.slice(minIndex, maxIndex + 1).map(c => c.id);

            if (onSelectionComplete) {
                onSelectionComplete({
                    startMinutes: startTime,
                    endMinutes: endTime,
                    courtIds: selectedCourts
                });
            }
        }

        // Optional: Keep selection visible until cleared?
        // For now, let's clear it, assuming a modal opens.
        // setSelectionStart(null);
        // setSelectionEnd(null);
    };

    const timerRef = useRef(null);

    // --- Touch Interaction (Mobile) ---

    // 1. Touch Start: Initiate Long Press Timer
    const handleTouchStart = (courtId, timeInMinutes) => {
        timerRef.current = setTimeout(() => {
            setIsDragging(true);
            setSelectionStart({ courtId, timeInMinutes });
            setSelectionEnd({ courtId, timeInMinutes });
            // Haptic Feedback
            if (window.navigator?.vibrate) window.navigator.vibrate(50);
        }, 500); // 500ms threshold for "Long Press"
    };

    // 2. Touch Move: Track Finger
    // Note: We attach this to the CELL, but the event continues even if we leave the cell.
    // Ideally, the grid container should handle moves, but local listeners work if we use elementFromPoint.
    const handleTouchMove = (e) => {
        // If we move BEFORE timer fires, it's a scroll -> Cancel Selection
        if (timerRef.current && !isDragging) {
            clearTimeout(timerRef.current);
            timerRef.current = null;
            return;
        }

        if (!isDragging) return;

        // If dragging, PREVENT SCROLL
        if (e.cancelable) e.preventDefault();

        const touch = e.touches[0];
        const el = document.elementFromPoint(touch.clientX, touch.clientY);

        if (el) {
            const cId = el.getAttribute('data-court-id');
            const tMin = el.getAttribute('data-time');

            if (cId && tMin) {
                // Update Selection
                setSelectionEnd({ courtId: cId, timeInMinutes: parseInt(tMin) });
            }
        }
    };

    // 3. Touch End: Finalize
    const handleTouchEnd = () => {
        // Clear timer if released early (Tap)
        if (timerRef.current) {
            clearTimeout(timerRef.current);
            timerRef.current = null;
        }

        if (isDragging) {
            handleMouseUp(); // Reuse finalization logic
        }
    };

    const cancelSelection = () => {
        setIsDragging(false);
        setSelectionStart(null);
        setSelectionEnd(null);
        if (timerRef.current) clearTimeout(timerRef.current);
    }

    // Calculate current selection rect for rendering
    const getSelectionBox = () => {
        if (!selectionStart || !selectionEnd) return null;
        return {
            start: {
                courtId: selectionStart.courtId,
                time: Math.min(selectionStart.timeInMinutes, selectionEnd.timeInMinutes)
            },
            end: {
                courtId: selectionEnd.courtId,
                time: Math.max(selectionStart.timeInMinutes, selectionEnd.timeInMinutes)
            }
        }
    };

    return {
        isDragging,
        handleMouseDown,
        handleMouseEnter,
        handleMouseUp,
        handleTouchStart,
        handleTouchMove,
        handleTouchEnd,
        cancelSelection,
        selectionBox: getSelectionBox()
    };
}
